  'Mountaineering': { zh: '登山', descEn: 'Prominently features characters discussing or hiking mountains.', descZh: '突出出现讨论或攀登高山的角色。' },
  'Noir': { zh: '黑色风格', descEn: 'Stylized as a cynical crime drama with low-key visuals.', descZh: '以冷峻视觉风格呈现的愤世嫉俗犯罪剧。' },
  'Otaku Culture': { zh: '御宅文化', descEn: 'Centers around the culture of a fanatical fan-base.', descZh: '围绕狂热粉丝群体的文化展开。' },
  'Pandemic': { zh: '瘟疫', descEn: 'Prominently features a disease prevalent over a whole country or the world.', descZh: '突出出现蔓延全国或全球的疾病。' },
  'Philosophy': { zh: '哲学', descEn: 'Relating or devoted to the study of the fundamental nature of knowledge, reality, and existence.', descZh: '关于或致力于研究知识、现实与存在的根本本质。' },
  'Politics': { zh: '政治', descEn: 'Centers around politics, politicians, or government activities.', descZh: '围绕政治、政客或政府活动展开。' },
  'Pregnancy': { zh: '怀孕', descEn: 'Features pregnant female characters or discusses the topic of pregnancy.', descZh: '包含怀孕的女性角色或讨论怀孕话题。' },
  'Prophecy': { zh: '预言', descEn: 'Features characters or plot elements that revolve around predicting the future.', descZh: '包含围绕预测未来展开的角色或剧情元素。' },
  'Proxy Battle': { zh: '代理战斗', descEn: 'A proxy battle is a battle where humans use creatures/robots to do the fighting for them, either by commanding those creatures/robots or by simply evolving them/changing them into battle mode.', descZh: '代理战斗指人类使用生物或机器人替自己作战，通过指挥它们或将其进化、切换为战斗模式。' },
