  'Reincarnation': { zh: '转生', descEn: 'Features a character being born again after death, typically as another person or in another world.', descZh: '包含死后重生（通常是另一个人或在另一个世界）的角色。' },
  'Religion': { zh: '宗教', descEn: 'Centers on the belief that humanity is related to supernatural, transcendental, and spiritual elements.', descZh: '围绕人类与超自然、超验和精神元素相关的信仰展开。' },
  'Rescue': { zh: '救援', descEn: 'Centers around operations that carry out urgent treatment of injuries, remove people from danger, or save lives. This includes series that are about search-and-rescue teams, trauma surgeons, firefighters, and more.', descZh: '围绕紧急救治伤员、将人脱离危险或拯救生命展开，包括搜救队、创伤外科医生、消防员等题材。' },
  'Royal Affairs': { zh: '王室政治', descEn: 'Features nobility, alliances, arranged marriage, succession disputes, religious orders and other elements of royal politics.', descZh: '包含贵族、联盟、包办婚姻、继承权争端、宗教团体等王室政治元素。' },
  'Slavery': { zh: '奴隶制', descEn: 'Prominently features slaves, slavery, or slave trade.', descZh: '突出出现奴隶、奴隶制度或奴隶贸易。' },
  'Software Development': { zh: '软件开发', descEn: 'Centers around characters developing or programming a piece of technology, software, gaming, etc.', descZh: '围绕角色开发或编写技术、软件、游戏等展开。' },
  'Survival': { zh: '生存', descEn: 'Centers around the struggle to live in spite of extreme obstacles.', descZh: '围绕在极端障碍下挣扎求生展开。' },
  'Terrorism': { zh: '恐怖主义', descEn: 'Centers around the activities of a terrorist or terrorist organization.', descZh: '围绕恐怖分子或恐怖组织的活动展开。' },
  'Torture': { zh: '酷刑', descEn: 'The act of deliberately inflicting severe pain or suffering upon another individual or oneself as a punishment or with a specific purpose.', descZh: '出于惩罚或特定目的，故意对他人或自己施加严重痛苦的行为。' },
  'Travel': { zh: '旅行', descEn: 'Centers around character(s) moving between places a significant distance apart.', descZh: '围绕角色在相距遥远的地点之间移动展开。' },
  'Vocal Synth': { zh: '电子歌姬', descEn: 'Features one or more singers or characters that are products of a synthesize singing program. Popular examples are Vocaloids, UTAUloids, and CeVIOs.', descZh: '包含一个或多个由合成歌声程序产生的歌手或角色，常见例子有Vocaloid、UTAUloid和CeVIO。' },
  'War': { zh: '战争', descEn: 'Partly or completely set during wartime.', descZh: '部分或完全设定在战争时期。' },
  // ── Setting-Universe ──
