  'Omegaverse': { zh: 'ABO世界观', descEn: 'Alternative universe that prominently features dynamics modeled after wolves in which there are alphas, betas, and omegas and heat cycles as well as impregnation, regardless of gender.', descZh: '以狼群社会为蓝本的平行世界观，包含 alpha、beta、omega 之分、发情期以及不分性别的受孕。' },
  'Post-Apocalyptic': { zh: '后末日', descEn: 'Partly or completely set in a world or civilization after a global disaster.', descZh: '部分或完全设定在全球灾难之后的世界或文明中。' },
