  'Urban Fantasy': { zh: '都市奇幻', descEn: 'Set in a world similar to the real world, but with the existence of magic or other supernatural elements.', descZh: '设定在与现实世界相似、但存在魔法或其他超自然元素的世界。' },
  'Virtual World': { zh: '虚拟世界', descEn: 'Partly or completely set in the world inside a video game.', descZh: '部分或完全设定在电子游戏的世界中。' },
