  'Age Gap': { zh: '年龄差', descEn: 'Prominently features romantic relations between people with a significant age difference.', descZh: '突出出现年龄差距悬殊的人物之间的恋爱关系。' },
  'Boys\' Love': { zh: 'BL', descEn: 'Prominently features romance between two males, not inherently sexual.', descZh: '突出描写两名男性之间的恋爱，并非必然涉及性。' },
