  'Cohabitation': { zh: '同居', descEn: 'Features two or more people who live in the same household and develop a romantic or sexual relationship.', descZh: '包含同住一屋檐下并发展出恋爱或性关系的两人或多人。' },
  'Female Harem': { zh: '后宫', descEn: 'Main cast features the protagonist plus several female characters who are romantically interested in them.', descZh: '主角加上多位对他有好感的女性角色构成主要阵容。' },
  'Heterosexual': { zh: '异性恋', descEn: 'Prominently features a romance between a man and a woman, not inherently sexual.', descZh: '突出描写男性和女性之间的恋爱，并非必然涉及性。' },
  'Incest': { zh: '近亲恋爱', descEn: 'Features sexual or romantic relations between characters who are related by blood.', descZh: '包含有血缘关系的角色之间的性爱或恋爱关系。' },
  'Inseki': { zh: '非血缘家人恋爱', descEn: 'Features sexual or romantic relations among step, adopted, and other non-blood related family members.', descZh: '包含继亲、收养等无血缘关系家庭成员之间的性爱或恋爱关系。' },
  'Interspecies': { zh: '跨种族恋爱', descEn: 'Romance between characters of different species.', descZh: '不同种族角色之间的恋爱。' },
