  'Mixed Gender Harem': { zh: '混合后宫', descEn: 'Main cast features the protagonist plus several people, regardless of gender, who are romantically interested in them.', descZh: '主角加上多位（不论性别）对他有好感的人构成主要阵容。' },
  'Polyamorous': { zh: '多角恋', descEn: 'Features a character who is in a consenting relationship with multiple people at one time.', descZh: '包含同时与多人保持自愿关系的角色。' },
  'Teens\' Love': { zh: '少女向恋爱', descEn: 'Sexually explicit love-story between individuals of the opposite sex, specifically targeting females of teens and young adult age.', descZh: '异性之间包含露骨性描写的恋爱故事，目标为少女及年轻女性。' },
  'Unrequited Love': { zh: '单恋', descEn: 'One or more characters are experiencing an unrequited love that may or may not be reciprocated.', descZh: '一个或多个角色经历的单恋，可能得到回应也可能没有。' },
  'Yuri': { zh: '百合', descEn: 'Prominently features romance between two females, not inherently sexual. Also known as Girls\' Love.', descZh: '突出描写两名女性之间的恋爱，并非必然涉及性，也称百合（Girls\' Love）。' },
  // ── Cast-Traits ──
  'Age Regression': { zh: '返老还童', descEn: 'Prominently features a character who was returned to a younger state.', descZh: '突出出现被变回年轻状态的角色。' },
