  'Anthropomorphism': { zh: '拟人化', descEn: 'Contains non-human character(s) that have attributes or characteristics of a human being.', descZh: '包含具有人类属性或特征的非人角色。' },
  'Aromantic': { zh: '无浪漫取向', descEn: 'Features a character who experiences little to no romantic attraction.', descZh: '包含几乎或完全不产生浪漫吸引的角色。' },
  'Arranged Marriage': { zh: '包办婚姻', descEn: 'Features two characters made to marry each other, usually by their family.', descZh: '包含两个被（通常是家人）安排结婚的角色。' },
  'Artificial Intelligence': { zh: '人工智能', descEn: 'Intelligent non-organic machines that work and react similarly to humans.', descZh: '能够像人类一样工作与反应的智能非有机机器。' },
  'Asexual': { zh: '无性取向', descEn: 'Features a character who isn\'t sexually attracted to people of any sex or gender.', descZh: '包含对任何性别的人都不产生性吸引的角色。' },
