  'Chimera': { zh: '合成兽', descEn: 'Features a beast made by combining animals, usually with humans.', descZh: '包含由动物（通常结合人类）组合而成的合成兽。' },
  'Chuunibyou': { zh: '中二病', descEn: 'Prominently features a character with "Middle School 2nd Year Syndrome", who either acts like a know-it-all adult or falsely believes they have special powers.', descZh: '突出出现患有"中二病"（chuunibyou，初中二年级症候群）的角色——要么装成无所不知的大人，要么妄信自己有超能力。' },
  'Clone': { zh: '克隆人', descEn: 'Prominently features a character who is an artificial exact copy of another organism.', descZh: '突出出现作为其他生物人工精确复制品的角色。' },
  'Cosplay': { zh: '角色扮演', descEn: 'Features dressing up as a different character or profession.', descZh: '包含打扮成其他角色或职业。' },
