  'Crossdressing': { zh: '异装', descEn: 'Prominently features a character dressing up as the opposite sex.', descZh: '突出出现打扮成异性的角色。' },
  'Cyborg': { zh: '改造人', descEn: 'Prominently features a human character whose physiological functions are aided or enhanced by artificial means.', descZh: '突出出现生理机能由人工手段辅助或强化的改造人角色。' },
  'Delinquents': { zh: '不良', descEn: 'Features characters with a notorious image and attitude, sometimes referred to as "yankees".', descZh: '包含形象与态度恶劣、有时被称为"yankee"的不良少年角色。' },
