  'Dinosaurs': { zh: '恐龙', descEn: 'Prominently features Dinosaurs, prehistoric reptiles that went extinct millions of years ago.', descZh: '突出出现数百万年前灭绝的史前爬行动物恐龙。' },
  'Disability': { zh: '残障', descEn: 'A work that features one or more characters with a physical, mental, cognitive, or developmental condition that impairs, interferes with, or limits the person\'s ability to engage in certain tasks or actions.', descZh: '包含一个或多个患有身体、精神、认知或发育障碍、从而损害或限制其从事某些活动能力的角色的作品。' },
