  'Hikikomori': { zh: '家里蹲', descEn: 'Prominently features a character who withdraws from social life, often seeking extreme isolation.', descZh: '突出出现脱离社会生活、常寻求极端封闭的角色。' },
  'Homeless': { zh: '无家可归', descEn: 'Prominently features a character that is homeless.', descZh: '突出出现无家可归的角色。' },
