  'Maids': { zh: '女仆', descEn: 'Prominently features a character who is a maid.', descZh: '突出出现女仆角色。' },
  'Mermaid': { zh: '人鱼', descEn: 'A mythological creature with the body of a human and the tail of a fish.', descZh: '拥有人类身体与鱼尾的神话生物。' },
  'Monster Boy': { zh: '人外男', descEn: 'Prominently features a male character who is a part-monster.', descZh: '突出出现半怪物的男性角色。' },
