  'Oiran': { zh: '花魁', descEn: 'Prominently features a courtesan character of the Japanese Edo Period.', descZh: '突出出现日本江户时代的花魁（高级游女）角色。' },
  'Ojou-sama': { zh: '大小姐', descEn: 'Features a wealthy, high-class, oftentimes stuck up and demanding female character.', descZh: '包含富裕、上流、往往傲慢任性的千金小姐角色。' },
