  'Robots': { zh: '机器人', descEn: 'Prominently features humanoid machines.', descZh: '突出出现人形机器。' },
  'Samurai': { zh: '武士', descEn: 'Prominently features warriors of medieval Japanese nobility bound by a code of honor.', descZh: '突出出现受荣誉准则约束的日本中世纪贵族武士。' },
  'Shrine Maiden': { zh: '巫女', descEn: 'Prominently features a character who is a shrine maiden.', descZh: '突出出现巫女角色。' },
